  const T = __game.race.track, topY = (x, z) => Math.max(T.ground2 ? T.ground2(x, z) : 0, 0) + 0.11;
  const pos = [], col = [], idx = [], id = new Int32Array((D.nx + 1) * (D.nz + 1)).fill(-1);
