    const al = Math.max(a(i - 1, j - 1), a(i, j - 1), a(i - 1, j), a(i, j)) > 0 ? (a(i - 1, j - 1) + a(i, j - 1) + a(i - 1, j) + a(i, j)) / 4 : 0;
